// A row owns this snapshot for its render lifetime. Rebuilding the authored UI
// drops it, so in-place edits cannot leave a global identity cache stale.
export class TimelineIntervalIndex{
 constructor(items){this.items=items;this.rows=items.map((item,index)=>{const start=item.start??item.time;return {item,index,start,end:start+Math.max(0,item.duration||0)};}).sort((a,b)=>a.start-b.start||a.index-b.index);const size=this.rows.length;this.maximum=new Float64Array(Math.max(1,size*4));const build=(node,low,high)=>{if(low>=high)return -Infinity;if(high-low===1)return this.maximum[node]=this.rows[low].end;const middle=(low+high)>>>1;return this.maximum[node]=Math.max(build(node*2+1,low,middle),build(node*2+2,middle,high));};build(0,0,size);}
 query(range,metrics){if(!range||!Number.isFinite(range.start)||!Number.isFinite(range.end)||range.end<range.start)throw Error('클립 표시 범위를 확인하세요.');if(metrics)Object.assign(metrics,{nodes:0,items:0,total:this.rows.length});let low=0,high=this.rows.length;while(low<high){const middle=(low+high)>>>1;if(this.rows[middle].start<=range.end)low=middle+1;else high=middle;}const stop=low,result=[],walk=(node,from,to)=>{if(metrics)metrics.nodes++;if(from>=stop||from>=to||this.maximum[node]<range.start)return;if(to-from===1){if(metrics)metrics.items++;result.push(this.rows[from]);return;}const middle=(from+to)>>>1;walk(node*2+1,from,middle);walk(node*2+2,middle,to);};walk(0,0,this.rows.length);return result.sort((a,b)=>a.index-b.index).map(row=>row.item);}
 queryPage(range,{offset=0,limit=64,selection,metrics}={}){
  if(!range||!Number.isFinite(range.start)||!Number.isFinite(range.end)||range.end<range.start||!Number.isInteger(offset)||offset<0||!Number.isInteger(limit)||limit<1||limit>256||selection!==undefined&&(typeof selection!=='string'||selection.length>160))throw Error('클립 페이지의 범위·offset·limit을 확인하세요.');
  const size=this.rows.length;if(!this.minimum){this.minimum=new Float64Array(this.maximum.length);const build=(node,from,to)=>{if(from>=to)return Infinity;if(to-from===1)return this.minimum[node]=this.rows[from].end;const middle=(from+to)>>>1;return this.minimum[node]=Math.min(build(node*2+1,from,middle),build(node*2+2,middle,to));};build(0,0,size);}
  if(metrics)Object.assign(metrics,{nodes:0,emitted:0,total:size});let low=0,high=size;while(low<high){const mid=(low+high)>>>1;if(this.rows[mid].start<=range.end)low=mid+1;else high=mid;}const stop=low,counts=new Map(),count=(node,from,to)=>{if(counts.has(node))return counts.get(node);if(metrics)metrics.nodes++;let n=0;if(from<stop&&from<to&&this.maximum[node]>=range.start){if(to<=stop&&this.minimum[node]>=range.start)n=to-from;else{const mid=(from+to)>>>1;n=count(node*2+1,from,mid)+count(node*2+2,mid,to);}}counts.set(node,n);return n;},total=count(0,0,size);
  if(selection!==undefined){if(!this.idRows){this.idRows=new Map();this.rows.forEach((row,rank)=>{const id=row.item.id;if(typeof id==='string')this.idRows.set(id,this.idRows.has(id)?null:{row,rank});});}const found=this.idRows.get(selection);if(found&&found.row.start<=range.end&&found.row.end>=range.start){const before=(node,from,to)=>{if(from>=found.rank)return 0;if(to<=found.rank)return count(node,from,to);const mid=(from+to)>>>1;return before(node*2+1,from,mid)+before(node*2+2,mid,to);};offset=Math.floor(before(0,0,size)/limit)*limit;}}
  const result=[],walk=(node,from,to)=>{const n=count(node,from,to);if(!n||result.length>=limit)return;if(skip>=n){skip-=n;return;}if(to-from===1){result.push(this.rows[from].item);return;}const mid=(from+to)>>>1;walk(node*2+1,from,mid);walk(node*2+2,mid,to);};let skip=offset;walk(0,0,size);if(metrics)metrics.emitted=result.length;
  return{total,offset,limit,items:result,nextOffset:offset+result.length<total?offset+result.length:null,previousOffset:offset?Math.max(0,offset-limit):null,order:'start-then-authored-index'};
 }
}
